"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import { CinematicStoryPlayer } from "@/components/CinematicStoryPlayer";
import { ProductCloudSavePanel } from "@/components/ProductCloudSavePanel";
import { downloadStoryCard } from "@/platform/export/story-card";
import { createLocalMediaAssets, revokeLocalMediaAssets, type LocalMediaAsset } from "@/platform/media/local";
import { trackProductEvent } from "@/platform/telemetry/client";
import { buildMyYearSummary, composeMyYearChapters, createMyYearShareManifest, type MyYearMoment } from "@/products/myyear/model";

function todayForYear(year: number) { const now = new Date(); return `${year}-${String(now.getMonth() + 1).padStart(2, "0")}-${String(now.getDate()).padStart(2, "0")}`; }

export function MyYearBuilder() {
  const [year, setYear] = useState(new Date().getFullYear()); const [title, setTitle] = useState(`My ${new Date().getFullYear()}`); const [moments, setMoments] = useState<MyYearMoment[]>([]); const [draftTitle, setDraftTitle] = useState(""); const [draftDate, setDraftDate] = useState(todayForYear(new Date().getFullYear())); const [draftCaption, setDraftCaption] = useState(""); const [draftLocation, setDraftLocation] = useState(""); const [photos, setPhotos] = useState<LocalMediaAsset[]>([]); const [momentMedia, setMomentMedia] = useState<Record<string, LocalMediaAsset[]>>({}); const photoRef = useRef<LocalMediaAsset[]>([]); const momentMediaRef = useRef<Record<string, LocalMediaAsset[]>>({}); const [active, setActive] = useState(0); const [message, setMessage] = useState("");
  useEffect(() => () => { revokeLocalMediaAssets(photoRef.current); for (const assets of Object.values(momentMediaRef.current)) revokeLocalMediaAssets(assets); }, []);
  useEffect(() => { const receiveImport = (event: Event) => { const incoming = (event as CustomEvent<MyYearMoment[]>).detail; if (!Array.isArray(incoming)) return; const accepted = incoming.filter((moment) => moment.date.startsWith(`${year}-`)).slice(0, 250); if (!accepted.length) { setMessage(`No calendar events matched ${year}. Change the year above, then import again.`); return; } setMoments((current) => [...current, ...accepted]); setMessage(`Imported ${accepted.length} local calendar ${accepted.length === 1 ? "event" : "events"}. Review them before sharing.`); }; window.addEventListener("threadtales:myyear-import", receiveImport); return () => window.removeEventListener("threadtales:myyear-import", receiveImport); }, [year]);
  const summary = useMemo(() => { try { return buildMyYearSummary(year, title, moments); } catch { return null; } }, [year, title, moments]); const chapters = useMemo(() => summary ? composeMyYearChapters(summary) : [], [summary]); const chapter = chapters[Math.min(active, Math.max(0, chapters.length - 1))]; const featuredPhoto = summary?.moments.map((moment) => momentMedia[moment.id]?.[0]).find(Boolean);
  function clearMedia() { revokeLocalMediaAssets(photoRef.current); photoRef.current = []; for (const assets of Object.values(momentMediaRef.current)) revokeLocalMediaAssets(assets); momentMediaRef.current = {}; setPhotos([]); setMomentMedia({}); }
  function changeYear(next: number) { clearMedia(); setYear(next); setTitle((current) => /^My \d{4}$/.test(current) ? `My ${next}` : current); setDraftDate(todayForYear(next)); setMoments([]); setActive(0); setMessage("Changing the year cleared the local draft so dates cannot silently cross years."); }
  function selectPhotos(files: FileList | null) { revokeLocalMediaAssets(photoRef.current); const next = createLocalMediaAssets(files, 12); photoRef.current = next; setPhotos(next); }
  function addMoment() { setMessage(""); if (!draftTitle.trim()) { setMessage("Give this moment a short title."); return; } if (!draftDate || !draftDate.startsWith(`${year}-`)) { setMessage(`Choose a date inside ${year}.`); return; } const id = crypto.randomUUID(); const moment: MyYearMoment = { id, title: draftTitle.trim(), date: draftDate, caption: draftCaption.trim() || undefined, location: draftLocation.trim() || undefined, photoCount: photos.length }; if (photos.length) { const attached = photos; photoRef.current = []; momentMediaRef.current = { ...momentMediaRef.current, [id]: attached }; setMomentMedia(momentMediaRef.current); setPhotos([]); } if (moments.length === 0) trackProductEvent("myyear_created", "myyear"); setMoments((current) => [...current, moment]); setDraftTitle(""); setDraftCaption(""); setDraftLocation(""); }
  function removeMoment(id: string) { revokeLocalMediaAssets(momentMediaRef.current[id] ?? []); const nextMedia = { ...momentMediaRef.current }; delete nextMedia[id]; momentMediaRef.current = nextMedia; setMomentMedia(nextMedia); setMoments((current) => current.filter((item) => item.id !== id)); }
  async function exportChapter() { if (!chapter) return; await downloadStoryCard(chapter, "vertical", true); trackProductEvent("story_exported", "myyear"); }
  async function copyShareSummary() { if (!summary) return; await navigator.clipboard.writeText(JSON.stringify(createMyYearShareManifest(summary))); trackProductEvent("share_created", "myyear"); setMessage("Copied a privacy-safe MyYear share manifest. Photo files, captions and locations are excluded by default."); }
  return <div className="product-builder" data-product="myyear"><section className="story product-workspace"><div className="chapter-head"><div><span className="story-summary-kicker">MyYear.World MVP</span><h2>Build your year from moments you choose.</h2><p>Selected photos use temporary browser object URLs for previews. Photo bytes are not placed in localStorage, public share summaries, or cloud-save payloads.</p></div></div><div className="builder-grid"><label>Year<input className="select" type="number" min="1900" max="2200" value={year} onChange={(event) => changeYear(Number(event.target.value))}/></label><label>Year title<input className="share-input" value={title} maxLength={80} onChange={(event) => setTitle(event.target.value)}/></label></div><div className="builder-card"><h3>Add a moment</h3><div className="builder-grid"><label>Title<input className="share-input" aria-label="MyYear moment title" value={draftTitle} maxLength={120} onChange={(event) => setDraftTitle(event.target.value)} placeholder="The trip we kept talking about"/></label><label>Date<input className="share-input" aria-label="MyYear moment date" type="date" value={draftDate} onChange={(event) => setDraftDate(event.target.value)}/></label><label>Location (optional)<input className="share-input" value={draftLocation} maxLength={120} onChange={(event) => setDraftLocation(event.target.value)} placeholder="Boston, MA"/></label><label>Caption (optional)<input className="share-input" value={draftCaption} maxLength={240} onChange={(event) => setDraftCaption(event.target.value)} placeholder="One line you want to remember"/></label></div><label className="file-drop">Selected photos (local preview only)<input aria-label="Choose MyYear photos" type="file" accept="image/*" multiple onChange={(event) => selectPhotos(event.target.files)}/></label>{photos.length ? <div className="local-media-grid" aria-label="MyYear selected photo previews">{photos.map((photo) => <figure key={photo.id}><img src={photo.objectUrl} alt="Selected local preview"/><figcaption>{photo.name}</figcaption></figure>)}</div> : null}<button className="btn btn-primary" onClick={addMoment}>Add moment</button></div>{message ? <div className="notice" role="status">{message}</div> : null}<div className="timeline-list" aria-label="MyYear timeline">{moments.length ? [...moments].sort((a,b)=>a.date.localeCompare(b.date)).map((moment) => <article key={moment.id}><div className="timeline-media-copy">{momentMedia[moment.id]?.length ? <div className="local-media-grid compact">{momentMedia[moment.id].slice(0,3).map((photo) => <figure key={photo.id}><img src={photo.objectUrl} alt={`${moment.title} local preview`}/></figure>)}</div> : null}<div><small>{moment.date}{moment.location ? ` · ${moment.location}` : ""}</small><h3>{moment.title}</h3><p>{moment.caption || `${moment.photoCount} selected photo${moment.photoCount === 1 ? "" : "s"}`}</p></div></div><button className="btn btn-soft" onClick={() => removeMoment(moment.id)}>Remove</button></article>) : <div className="notice">Add at least one moment to generate your year recap.</div>}</div></section>
    {summary && chapter ? <><section className="story chapter-deck" aria-label="MyYear story chapters"><div className="chapter-head"><div><span className="story-summary-kicker">Year recap</span><h3>{summary.title} · {chapters.length} chapters</h3><p>{summary.moments.length} moments across {summary.eras.length} deterministic eras.</p></div><div className="premium-actions"><button className="btn btn-primary" onClick={() => void exportChapter()}>Download 9:16 card</button><button className="btn btn-soft" onClick={() => void copyShareSummary()}>Copy safe share summary</button></div></div><div className="chapter-preview theme-violet">{featuredPhoto ? <img className="story-local-photo" src={featuredPhoto.objectUrl} alt="Selected MyYear local story preview"/> : null}<small>{chapter.type.replace("-", " ")}</small><h3>{chapter.title}</h3>{chapter.metric !== undefined ? <strong>{chapter.metric}</strong> : null}{chapter.subtitle ? <span>{chapter.subtitle}</span> : null}{chapter.supportingText ? <p>{chapter.supportingText}</p> : null}<div className="chapter-privacy">{chapter.privacyLevel === "safe" ? "Share-safe derived fact" : "Personal moment · local unless selected"}</div></div><div className="chapter-nav"><button className="btn btn-soft" disabled={active === 0} onClick={() => setActive((value) => Math.max(0, value - 1))}>← Previous</button><div className="chapter-dots">{chapters.map((item,index)=><button key={item.id} aria-label={`Open MyYear chapter ${index + 1}`} className={index===active?"active":""} onClick={()=>setActive(index)}/>)}</div><button className="btn btn-soft" disabled={active === chapters.length - 1} onClick={() => setActive((value) => Math.min(chapters.length - 1, value + 1))}>Next →</button></div></section><CinematicStoryPlayer chapters={chapters} themeId="paper"/><ProductCloudSavePanel product="myyear" title={summary.title} result={summary} description="MyYear cloud save stores the derived timeline only after sign-in. Temporary browser photo object URLs and image bytes are excluded."/></> : null}</div>;
}

"use client";

import { useRef, useState } from "react";
import type { MyYearMoment } from "@/products/myyear/model";

export function calendarMoments(text: string): MyYearMoment[] {
  const blocks = text.replace(/\r?\n[ \t]/g, "").split("BEGIN:VEVENT").slice(1);
  return blocks.slice(0, 250).map((block, index) => {
    const read = (name: string) => block.match(new RegExp(`^${name}(?:;[^:]*)?:(.+)$`, "mi"))?.[1]?.trim() ?? "";
    const rawDate = read("DTSTART");
    const date = /^\d{8}/.test(rawDate) ? `${rawDate.slice(0, 4)}-${rawDate.slice(4, 6)}-${rawDate.slice(6, 8)}` : "";
    return { id: `ics-${index}-${crypto.randomUUID()}`, date, title: read("SUMMARY").slice(0, 120) || `Calendar event ${index + 1}`, caption: read("DESCRIPTION").slice(0, 240) || undefined, location: read("LOCATION").slice(0, 120) || undefined, photoCount: 0 };
  }).filter((moment) => Boolean(moment.date));
}

export function MyYearCalendarImport() {
  const input = useRef<HTMLInputElement>(null);
  const [message, setMessage] = useState("");
  async function importCalendar(file: File | undefined) {
    if (!file) return;
    if (file.size > 2_000_000) { setMessage("Choose a calendar file under 2 MB. It is read only in this browser."); return; }
    const moments = calendarMoments(await file.text());
    if (!moments.length) { setMessage("No VEVENT records were found in that .ics file."); return; }
    window.dispatchEvent(new CustomEvent<MyYearMoment[]>("threadtales:myyear-import", { detail: moments }));
    setMessage(`${moments.length} calendar entries were prepared locally for the selected MyYear.`);
  }
  return <section className="builder-card" aria-label="MyYear calendar import"><h3>Import a calendar</h3><p className="notice">Import an exported .ics file. Calendar data stays local, and only events that match the year selected above are added.</p><button className="btn btn-soft" onClick={() => input.current?.click()}>Choose .ics calendar</button><input ref={input} className="file-input" aria-label="Choose MyYear calendar" type="file" accept=".ics,text/calendar" onChange={(event) => void importCalendar(event.target.files?.[0])}/>{message ? <p className="notice" role="status">{message}</p> : null}</section>;
}

"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import { PetLifeHouseholdPanel } from "@/components/PetLifeHouseholdPanel";
import { ProductCloudSavePanel } from "@/components/ProductCloudSavePanel";
import { downloadStoryCard } from "@/platform/export/story-card";
import { createLocalMediaAssets, revokeLocalMediaAssets, type LocalMediaAsset } from "@/platform/media/local";
import { trackProductEvent } from "@/platform/telemetry/client";
import { buildPetLifeRecap, composePetLifeChapters, composePetLifeMemorialChapters, createPetLifeShareManifest, type PetMemory, type PetMemoryType, type PetProfile } from "@/products/petlife/model";

const LOCAL_KEY = "story-platform:petlife:v1";
interface LocalPetLifeState { profile: PetProfile | null; memories: PetMemory[]; }
function persistLocal(state: LocalPetLifeState) { window.localStorage.setItem(LOCAL_KEY, JSON.stringify(state)); }

export function PetLifeBuilder() {
  const [profile, setProfile] = useState<PetProfile | null>(null);
  const [memories, setMemories] = useState<PetMemory[]>([]);
  const [restored, setRestored] = useState(false);
  const [name, setName] = useState(""); const [species, setSpecies] = useState("Dog"); const [birthday, setBirthday] = useState(""); const [adoptionDate, setAdoptionDate] = useState("");
  const [memoryTitle, setMemoryTitle] = useState(""); const [memoryDate, setMemoryDate] = useState(new Date().toISOString().slice(0, 10)); const [memoryNote, setMemoryNote] = useState(""); const [memoryType, setMemoryType] = useState<PetMemoryType>("memory");
  const [selectedMedia, setSelectedMedia] = useState<LocalMediaAsset[]>([]);
  const [sessionMedia, setSessionMedia] = useState<Record<string, LocalMediaAsset[]>>({});
  const selectedMediaRef = useRef<LocalMediaAsset[]>([]);
  const sessionMediaRef = useRef<Record<string, LocalMediaAsset[]>>({});
  const [recapYear, setRecapYear] = useState(new Date().getFullYear()); const [active, setActive] = useState(0); const [message, setMessage] = useState(""); const [includePetName, setIncludePetName] = useState(false); const [memorialMode, setMemorialMode] = useState(false);

  useEffect(() => { const frame = window.requestAnimationFrame(() => { try { const raw = window.localStorage.getItem(LOCAL_KEY); if (raw) { const parsed = JSON.parse(raw) as LocalPetLifeState; if (parsed.profile?.id && Array.isArray(parsed.memories)) { setProfile(parsed.profile); setMemories(parsed.memories); setName(parsed.profile.name); setSpecies(parsed.profile.species); setBirthday(parsed.profile.birthday ?? ""); setAdoptionDate(parsed.profile.adoptionDate ?? ""); } } } catch { window.localStorage.removeItem(LOCAL_KEY); } finally { setRestored(true); } }); return () => window.cancelAnimationFrame(frame); }, []);
  useEffect(() => () => { revokeLocalMediaAssets(selectedMediaRef.current); for (const assets of Object.values(sessionMediaRef.current)) revokeLocalMediaAssets(assets); }, []);

  const recap = useMemo(() => { if (!profile) return null; try { return buildPetLifeRecap(profile, memories, recapYear); } catch { return null; } }, [profile, memories, recapYear]);
  const chapters = useMemo(() => recap ? (memorialMode ? composePetLifeMemorialChapters(recap) : composePetLifeChapters(recap)) : [], [recap, memorialMode]);
  const chapter = chapters[Math.min(active, Math.max(0, chapters.length - 1))];
  const activeMemoryId = chapter?.id.startsWith("pet-") && !["pet-cover","pet-scale","pet-busiest","pet-closing"].includes(chapter.id) ? chapter.id.slice(4) : null;
  const featuredMedia = activeMemoryId ? sessionMedia[activeMemoryId]?.[0] : Object.values(sessionMedia).flat()[0];

  function selectPhotos(files: FileList | null) { revokeLocalMediaAssets(selectedMediaRef.current); const next = createLocalMediaAssets(files, 12); selectedMediaRef.current = next; setSelectedMedia(next); }
  function saveProfile() { if (!name.trim() || !species.trim()) { setMessage("Add a pet name and species first."); return; } const creating = !profile; const next: PetProfile = profile ? { ...profile, name: name.trim(), species: species.trim(), birthday: birthday || undefined, adoptionDate: adoptionDate || undefined } : { id: crypto.randomUUID(), name: name.trim(), species: species.trim(), birthday: birthday || undefined, adoptionDate: adoptionDate || undefined }; setProfile(next); persistLocal({ profile: next, memories: profile ? memories : [] }); if (creating) { setMemories([]); trackProductEvent("pet_created", "petlife"); } setMessage(`${next.name}'s profile is saved on this device.`); }
  function addMemory() { if (!profile) { setMessage("Create the pet profile before adding memories."); return; } if (!memoryTitle.trim() || !memoryDate) { setMessage("Add a memory title and date."); return; } const id = crypto.randomUUID(); const memory: PetMemory = { id, petId: profile.id, type: memoryType, date: memoryDate, title: memoryTitle.trim(), note: memoryNote.trim() || undefined, photoCount: selectedMedia.length }; const next = [...memories, memory]; if (selectedMedia.length) { sessionMediaRef.current = { ...sessionMediaRef.current, [id]: selectedMedia }; setSessionMedia(sessionMediaRef.current); selectedMediaRef.current = []; setSelectedMedia([]); } const hasRecapMemory = memories.some((item) => item.date.startsWith(`${recapYear}-`)); setMemories(next); persistLocal({ profile, memories: next }); trackProductEvent("pet_memory_added", "petlife"); if (!hasRecapMemory && memory.date.startsWith(`${recapYear}-`)) trackProductEvent("annual_recap_created", "petlife"); setMemoryTitle(""); setMemoryNote(""); setMessage(memoryType === "milestone" ? "Milestone added." : "Memory added."); }
  function removeMemory(id: string) { if (!profile) return; revokeLocalMediaAssets(sessionMediaRef.current[id] ?? []); const nextMedia = { ...sessionMediaRef.current }; delete nextMedia[id]; sessionMediaRef.current = nextMedia; setSessionMedia(nextMedia); const next = memories.filter((memory) => memory.id !== id); setMemories(next); persistLocal({ profile, memories: next }); }
  function clearLocal() { revokeLocalMediaAssets(selectedMediaRef.current); selectedMediaRef.current = []; for (const assets of Object.values(sessionMediaRef.current)) revokeLocalMediaAssets(assets); sessionMediaRef.current = {}; setSelectedMedia([]); setSessionMedia({}); window.localStorage.removeItem(LOCAL_KEY); setProfile(null); setMemories([]); setName(""); setSpecies("Dog"); setBirthday(""); setAdoptionDate(""); setMemorialMode(false); setMessage("Local PetLife data was deleted from this browser."); }
  async function exportChapter() { if (!chapter) return; await downloadStoryCard(chapter, "vertical", true); trackProductEvent("story_exported", "petlife"); }
  async function copyShareSummary() { if (!recap) return; await navigator.clipboard.writeText(JSON.stringify(createPetLifeShareManifest(recap, includePetName))); trackProductEvent("share_created", "petlife"); setMessage(`Copied a privacy-safe recap manifest${includePetName ? " with the pet name" : " without the pet name"}. Notes and photo files are excluded.`); }

  if (!restored) return <div className="notice">Opening your local PetLife timeline…</div>;
  return <div className="product-builder" data-product="petlife">
    <section className="story product-workspace"><div className="chapter-head"><div><span className="story-summary-kicker">PetLife MVP</span><h2>A private timeline that is useful between annual recaps.</h2><p>Profile and memory text persist locally. Selected image bytes are session-only browser object URLs; localStorage keeps only the existing photo count.</p></div></div>
      <div className="builder-card"><h3>{profile ? `Edit ${profile.name}` : "Create a pet profile"}</h3><div className="builder-grid"><label>Pet name<input className="share-input" aria-label="Pet name" value={name} maxLength={80} onChange={(event)=>setName(event.target.value)}/></label><label>Species<input className="share-input" aria-label="Pet species" value={species} maxLength={60} onChange={(event)=>setSpecies(event.target.value)}/></label><label>Birthday (optional)<input className="share-input" type="date" value={birthday} onChange={(event)=>setBirthday(event.target.value)}/></label><label>Adoption day (optional)<input className="share-input" type="date" value={adoptionDate} onChange={(event)=>setAdoptionDate(event.target.value)}/></label></div><div className="premium-actions"><button className="btn btn-primary" onClick={saveProfile}>{profile ? "Update profile" : "Create pet"}</button>{profile ? <button className="btn btn-soft" onClick={clearLocal}>Delete local PetLife data</button> : null}</div></div>
